//! Cargo-driven `winhttp.dll` link, generated by tools/cargo_cell_gen.py
//! from the cmake link it replaces.
//! The module is C, compiled and linked by reactos-link: there is no Rust body.

use reactos_link::{Linker, ModuleKind, MsvcrtexKind};
use std::env;

fn main() {
    let arch = env::var("CARGO_CFG_TARGET_ARCH").expect("CARGO_CFG_TARGET_ARCH");
    let (target_json, entry, image_base) = match arch.as_str() {
        "x86" => ("i686-pc-windows-gnu", "_DllMainCRTStartup@12", Some(0x6cb10000u64)),
        "x86_64" => ("x86_64-pc-windows-gnu", "DllMainCRTStartup", Some(0x7fe4b000000u64)),
        "aarch64" => ("aarch64-pc-windows-gnullvm", "DllMainCRTStartup", Some(0x7fe4b000000u64)),
        o => panic!("winhttp-cargo: unsupported arch {o}"),
    };

    let link_order: &[&str] = match arch.as_str() {
        "x86" => &["engine:uuid", "engine:wine", "import:oleaut32", "import:crypt32", "import:secur32", "import:user32", "import:advapi32", "import:ws2_32", "import:jsproxy", "import:kernel32_vista", "import:msvcrt", "import:kernel32", "import:ntdll", "engine:delayimp_rust", "body", "engine:oldnames"],
        "x86_64" => &["engine:uuid", "engine:wine", "import:oleaut32", "import:crypt32", "import:secur32", "import:user32", "import:advapi32", "import:ws2_32", "import:jsproxy", "import:kernel32_vista", "import:msvcrt", "import:kernel32", "import:ntdll", "engine:delayimp_rust", "body", "engine:oldnames"],
        "aarch64" => &["engine:uuid", "engine:wine", "import:oleaut32", "import:crypt32", "import:secur32", "import:user32", "import:advapi32", "import:ws2_32", "import:jsproxy", "import:kernel32_vista", "import:msvcrt", "import:kernel32", "import:ntdll", "engine:delayimp_rust", "body", "engine:oldnames"],
        _ => unreachable!(),
    };

    // The module's part of cmake's windres command; reactos-link adds what every
    // module shares from reactos-link/cflags/rc.<arch>.flags (Linker::rc).
    let rc_includes: &[&str] = &[
        "@build/dll/win32/winhttp",
        "dll/win32/winhttp",
        "@build/sdk/include/wine",
        "sdk/include/wine",
        "@std",
        "vendor/opengl-headers/include",
        "vendor/libdxg/include",
        "sdk/lib/pseh/include",
        "sdk/lib/tdilib",
        "vendor/zlib/include",
        "vendor/libtiff/include",
    ];
    let rc_flags: &[&str] = &[];
    let rc_defines: &[&str] = &[
        "WINVER=0x502",
        "_CRT_DECLARE_NONSTDC_NAMES=1",
        "_CRT_NONSTDC_NO_DEPRECATE",
        "_DLL",
        "_WIN32_WINNT=0x600",
        "_WINE",
        "__USE_CRTIMP",
        "__WINESRC__",
    ];

    Linker::new(target_json)
        .c_from_compile_db("winhttp_shims", &["dll/win32/winhttp/cookie.c", "dll/win32/winhttp/handle.c", "dll/win32/winhttp/main.c", "dll/win32/winhttp/net.c", "dll/win32/winhttp/request.c", "dll/win32/winhttp/session.c", "dll/win32/winhttp/url.c"])
        .rc("dll/win32/winhttp/rsrc.rc", rc_includes, rc_flags, rc_defines)
        .spec2def("dll/win32/winhttp/winhttp.spec", "winhttp.dll")
        .delay_import_lib("dll/win32/oleaut32/oleaut32.spec", "oleaut32.dll", "oleaut32")
        .delay_import_lib("dll/win32/crypt32/crypt32.spec", "crypt32.dll", "crypt32")
        .delay_import_lib("dll/win32/secur32/secur32.spec", "secur32.dll", "secur32")
        .import_lib("win32ss/user/user32/user32.spec", "user32.dll", "user32")
        .import_lib("dll/win32/advapi32/advapi32.spec", "advapi32.dll", "advapi32")
        .import_lib("dll/win32/ws2_32/ws2_32.spec", "ws2_32.dll", "ws2_32")
        .import_lib("dll/win32/jsproxy/jsproxy.spec", "jsproxy.dll", "jsproxy")
        .import_lib("dll/win32/kernel32/kernel32_vista/kernel32_vista.spec", "kernel32_vista.dll", "kernel32_vista")
        .import_lib("dll/win32/msvcrt/msvcrt.spec", "msvcrt.dll", "msvcrt")
        .import_lib("dll/win32/kernel32/kernel32.spec", "kernel32.dll", "kernel32")
        .import_lib("dll/ntdll/def/ntdll.spec", "ntdll.dll", "ntdll")
        // The body, import libs and static libs in cmake's link order: the first
        // to define a symbol wins. cmake-built ones are reused until each has a
        // cargo home; `engine:` ones reactos-link builds.
        .link_order(link_order)
        .msvcrtex_crt(MsvcrtexKind::Dll)
        .link(ModuleKind::Win32Dll {
            entry: entry.into(),
            image_base,
            subsystem: None,
        });
}
